package chatui

const ChatVoiceStyles = `.chatvoice-tool{position:relative;display:inline-flex;flex:none}.chatvoice-panel{z-index:1500;overflow:auto;box-shadow:var(--hcm-shadow-raised)}.chatvoice-tool>[hidden]{display:none!important}.chatvoice-bar-2{height:2px!important}.chatvoice-bar-3{height:3px!important}.chatvoice-bar-4{height:4px!important}.chatvoice-bar-5{height:5px!important}.chatvoice-bar-6{height:6px!important}.chatvoice-bar-7{height:7px!important}.chatvoice-bar-8{height:8px!important}.chatvoice-bar-9{height:9px!important}.chatvoice-bar-10{height:10px!important}.chatvoice-bar-11{height:11px!important}.chatvoice-bar-12{height:12px!important}.chatvoice-bar-13{height:13px!important}.chatvoice-bar-14{height:14px!important}.chatvoice-bar-15{height:15px!important}.chatvoice-bar-16{height:16px!important}.chatvoice-bar-17{height:17px!important}.chatvoice-bar-18{height:18px!important}.chatvoice-bar-19{height:19px!important}.chatvoice-bar-20{height:20px!important}.chatvoice-bar-21{height:21px!important}.chatvoice-bar-22{height:22px!important}.chatvoice-bar-23{height:23px!important}.chatvoice-bar-24{height:24px!important}.chatvoice{box-sizing:border-box;min-width:0;max-width:100%;width:100%;padding:12px;border:1px solid var(--hcm-border,var(--line));border-radius:var(--hcm-radius-control);background:var(--hcm-surface,var(--surface));color:var(--hcm-text,var(--ink));overflow-wrap:anywhere}.chatvoice audio{display:block;width:100%;max-width:100%;min-width:0}.chatvoice-controls{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.chatvoice button,.chatvoice select,.chatvoice input{min-height:44px;max-width:100%;border:1px solid var(--hcm-border,var(--line));border-radius:var(--hcm-radius-control);background:var(--hcm-surface,var(--surface));color:var(--hcm-text,var(--ink))}.chatvoice button:focus-visible,.chatvoice select:focus-visible,.chatvoice input:focus-visible,.chatvoice summary:focus-visible{outline:2px solid var(--hcm-accent,var(--accent));outline-offset:2px}.chatvoice-transcript{height:12em;overflow-y:auto;overscroll-behavior:contain}.chatvoice-preview-text{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3;max-height:4.5em;overflow:hidden}.chatvoice-transcript:has([data-chat-disclosure][open]) .chatvoice-preview-text{display:none}.chatvoice-transcript-text{line-height:1.5;white-space:pre-wrap}.chatvoice .chat-disclosure-button{min-height:44px;cursor:pointer}.chatvoice-segment[aria-current=true]{background:var(--hcm-accent-soft,var(--soft))}.chatvoice-low{border-block-end:1px dashed var(--hcm-border,var(--line))}.chatvoice-waveform{display:flex;height:24px;gap:2px;align-items:center;overflow:hidden}.chatvoice-waveform span{flex:1;background:var(--hcm-accent,var(--accent));min-width:1px;height:2px}.chatvoice-status{min-height:3em}.chatvoice-note{width:100%;box-sizing:border-box}.chatvoice [hidden]{display:none!important}@media(max-width:400px){.chatvoice{padding:8px}.chatvoice-controls>*{flex:1 1 auto}}@media(prefers-reduced-motion:reduce){.chatvoice *{animation:none!important;transition:none!important;scroll-behavior:auto!important}}`
